missing = []
for es, en in PAIRS:
    if es not in out:
        missing.append(es[:80])
        continue
    out = out.replace(es, en)
if missing:
    raise SystemExit("Pares sin match (actualizá build.py):\n  " + "\n  ".join(missing))

(ROOT / "en").mkdir(exist_ok=True)
(ROOT / "en" / "index.html").write_text(out, encoding="utf-8")
